UPDATE ai_prompt_templates
SET body = 'Создай фотореалистичную визуализацию полного образа на аватаре пользователя. Единственный главный объект результата - тот же человек с исходного аватара, полный рост. Сохрани личность, лицо, волосы, тон кожи, возрастное впечатление, рост, позу и пропорции тела. Замени только одежду на описанный стилистом комплект, добавь уместные обувь и аксессуары. Запрещено добавлять животных, лисиц, маскотов, фантазийных персонажей, лес, заросли и превращать человека в не-человеческий образ. Результат: вертикальное фото 3:4, полный рост, аккуратный нейтральный свет, реалистичный фон студии или городской интерьер, без эротизации и без изменения фигуры.'
WHERE template_key = 'stylist.preview_tryon_ru'
  AND body = 'Создай фотореалистичную визуализацию полного образа на аватаре пользователя. Сохрани личность, лицо, волосы, тон кожи, возрастное впечатление, рост и пропорции тела. Замени одежду на описанный стилистом комплект, добавь уместные обувь и аксессуары. Результат: вертикальное фото 3:4, полный рост, аккуратный свет, без эротизации и без изменения фигуры.';
